function christmasGallery(q){
 const items=christmasCrafts.filter(a=>(a[2]+" "+a[3]).toLocaleLowerCase("sv").includes(q));
 return '<div class="halloween-craft-grid christmas-craft-grid">'+items.map(a=>{const index=christmasCrafts.indexOf(a),file=seasonalCraftImages[a[2]];return '<article class="halloween-craft-card"><button type="button" class="halloween-craft-open" data-ccraft="'+index+'"><img class="craft-photo" src="./assets/seasonal/'+file+'" alt="Färdigt julpyssel: '+a[2]+'" loading="lazy" decoding="async"><span class="halloween-craft-title"><span>'+a[0]+'</span><strong>'+a[2]+'</strong><small>'+a[4]+'</small></span></button></article>'}).join("")+'</div>'+(items.length?'':'<p class="empty">Inga julpyssel matchar sökningen.</p>')
}
function halloweenGallery(q){
 const items=halloweenCrafts.filter(a=>(a[2]+" "+a[3]).toLocaleLowerCase("sv").includes(q));
 return '<div class="halloween-craft-grid halloween-craft-sheet">'+items.map(a=>{const index=halloweenCrafts.indexOf(a),file=seasonalCraftImages[a[2]];return '<article class="halloween-craft-card"><button type="button" class="halloween-craft-open" data-hcraft="'+index+'"><img class="craft-photo" src="./assets/seasonal/'+file+'" alt="Färdigt Halloweenpyssel: '+a[2]+'" loading="lazy" decoding="async"><span class="halloween-craft-title"><span>'+a[0]+'</span><strong>'+a[2]+'</strong><small>'+a[4]+'</small></span></button></article>'}).join("")+'</div>'+(items.length?'':'<p class="empty">Inga Halloweenpyssel matchar sökningen.</p>')
}

