function mandalaGallery(q){
const christmasOn=document.body.classList.contains("christmas");const styles=["Alla","Djur","Bakverk","Bilar","Vår","Sommar","Höst","Vinter","Halloween","Pokémon","Superhjältar","Fotbollsproffs","Fotbollslag","Squishy"].filter(v=>"Alla"||mandalas.some(m=>m.type===v||m.types?.includes(v))).concat(christmasOn?["Jul"]:[]);
const football=mandalaStyle==="Fotbollslag",leagues=["Alla","Allsvenskan","Premier League","La Liga"];
const leagueFilters=football?'<div class="mandala-intro"><p>Klubbmärken att färglägga - en bild per sida. Välj liga eller sök efter ditt lag.</p></div><div class="mandala-types coloring-types" role="group" aria-label="Ligor">'+leagues.map(v=>'<button type="button" class="mandala-type '+(v===footballLeague?"active":"")+'" data-football-league="'+v+'" aria-pressed="'+(v===footballLeague)+'">'+v+"</button>").join("")+"</div>":"";
let shown=mandalas.filter(m=>(!football||footballLeague==="Alla"||m.league===footballLeague)&&m.type!=="Blommor & blad"&&!m.types?.includes("Blommor & blad")&&(m.type!=="Jul"||christmasOn)&&(mandalaStyle==="Alla"||m.type===mandalaStyle||m.types?.includes(mandalaStyle))&&(m.title+" "+m.type+" "+(m.league||"")).toLocaleLowerCase("sv").includes(q));
return '<div class="mandala-intro"><strong>Välj ett tema att färglägga</strong></div><div class="mandala-types coloring-types" role="group" aria-label="Kategorier för färgläggning">'+styles.map(v=>'<button type="button" class="mandala-type '+(v===mandalaStyle?"active":"")+'" data-mstyle="'+v+'" aria-pressed="'+(v===mandalaStyle)+'">'+v+"</button>").join("")+'</div>'+leagueFilters+'<div class="mandala-grid">'+shown.map(m=>'<article class="mandala-card"><a href="'+(m.pdf||m.img)+'" target="_blank" rel="noopener"><img loading="lazy" decoding="async" src="'+(m.preview||m.img)+'" alt="Helsidesförhandsvisning av '+m.title+'"></a><div class="mandala-info"><span class="mandala-label">'+(m.league?m.league+" · "+m.season:(mandalaStyle!=="Alla"&&m.types?.includes(mandalaStyle)?mandalaStyle:m.type))+'</span><h3>'+m.title+'</h3><div class="mandala-links"><a href="'+(m.pdf||m.img)+'" target="_blank" rel="noopener">Öppna / skriv ut</a><a href="'+m.src+'" target="_blank" rel="noopener">'+(m.sourceLabel|| (m.pdf?"Källa: Monday Mandala":"Källa & licens"))+'</a>'+(m.src2?'<a href="'+m.src2+'" target="_blank" rel="noopener">Super Coloring</a>':"")+'</div></div></article>').join("")+'</div>'+(shown.length?"":'<div class="empty">Inga bilder i den här gruppen.</div>')
}function dollGallery(q){return '<div class="mandala-intro"><strong>Färglägg, klipp ut och klä på</strong><p>Välj en mall och öppna den för att skriva ut. Skriv gärna ut på lite tjockare papper. Klipp ut dockan och kläderna längs ytterlinjerna.</p></div><div class="mandala-grid">'+paperDolls.filter(m=>(m.title+" "+m.type+" "+(m.league||"")).toLocaleLowerCase("sv").includes(q)).map(m=>'<article class="mandala-card"><a href="'+m.img+'" target="_blank" rel="noopener"><img loading="lazy" src="'+m.img+'" alt="'+m.title+'"></a><div class="mandala-info"><span class="mandala-label">'+m.type+'</span><h3>'+m.title+'</h3><div class="mandala-links"><a href="'+m.img+'" target="_blank" rel="noopener">Öppna / skriv ut</a>' + (m.src?'<a href="'+m.src+'" target="_blank" rel="noopener">Källa &amp; licens</a>':'') + '</div></div></article>').join("")+'</div>'}

