const drawingDirections={
katt:["Rita en cirkel för huvudet och en oval för kroppen. Lägg till en mittlinje.","Forma öron, bröst, bakdel, tassar och den böjda svansen.","Placera ögon, liten nos, mun och morrhår på hjälplinjen.","Gör konturen tydlig, lägg till pälsstreck och sudda hjälplinjerna."],
hund:["Börja med huvud och kropp som två mjuka ovaler.","Rita hängande öron, nosparti, ben, tassar och svans.","Lägg till ögon, nos och ett vänligt litet leende.","Avsluta med päls, tasslinjer och en ren kontur."],
kanin:["Rita en rund huvudform, en oval kropp och två långa öron.","Forma kinderna, ryggen, bakbenen och de små framtassarna.","Lägg till ögon, nos, mun och morrhår.","Rita öronens insidor, päls och en liten rund svans."],
fjaril:["Markera en smal kropp och mittlinje.","Rita två stora övre vingar och två mindre nedre vingar.","Lägg till antenner och symmetriska vingmönster.","Fyll i tydliga mönster på båda sidor och förstärk konturen."],
panda:["Börja med en stor huvudcirkel och en rund kropp.","Lägg till öron, armar, ben och tassar.","Rita ögonfläckar, ögon, nos och mun.","Fyll i pandaögonens svarta fält och små pälsdetaljer."],
lejon:["Markera huvud, kropp och ben med enkla former.","Bygg en stor man runt ansiktet och forma kroppen.","Rita ögon, nos, mun, öron och tydliga tassar.","Lägg till manens hårstrån, svans och små pälsdetaljer."],
rav:["Börja med huvud, kropp och en stor svans som grundformer.","Forma spetsiga öron, smal nos, ben och den yviga svansen.","Placera ögon, nos och den ljusa ansiktsformen.","Lägg till pälsstrån och svansens spets."],
elefant:["Rita en oval kropp och en mindre cirkel för huvudet.","Forma stora öron, fyra stadiga ben och en lång snabel.","Lägg till öga, mun, snabelveck och tånaglar.","Rita hudveck och förstärk elefantens tydliga kontur."],
uggla:["Markera en upprätt kropp och två huvudtofsar.","Forma vingar, bröst, stjärt och fötter.","Rita två stora ögon och en liten näbb.","Lägg till fjädermönster på bröst och vingar."],
skoldpadda:["Rita en rundad kropp och ett stort skal som grundformer.","Forma huvud, ben och en liten svans.","Rita ögon, mun och skalmönstrets stora fält.","Lägg till skalsegment och små tådetaljer."],
dinosaurie:["Börja med huvud, kropp och svans som enkla former.","Bygg en igenkännbar kropp med ryggplattor, ben och armar.","Lägg till öga, mun och tydliga klor.","Rita plattornas mönster och små huddetaljer."],
giraff:["Markera kropp, långt halsstreck och huvud med hjälpcirklar.","Forma den långa halsen, benen, öronen och små hornen.","Lägg till ögon, nos och giraffens fläckar.","Fyll kroppen med tydliga fläckar och avsluta hovarna."],
hast:["Rita stora former för kropp, hals och huvud.","Forma fyra ben, hovar, öron och svans.","Lägg till öga, mule och manens riktning.","Rita man, svanshår och enkla muskellinjer."],
tiger:["Markera huvud, kropp och svans med grundformer.","Bygg upp ben, öron, nosparti och lång svans.","Lägg till ögon, nos och ansiktets markeringar.","Rita tydliga tigerstrimmor som följer kroppens form."],
drake:["Rita kropp, huvud och svans som enkla grundformer.","Lägg till ben, vingar, horn och en lång svans.","Rita öga, nos och vingarnas leder.","Fyll på med fjäll, klor och några tydliga vingskal."],
varg:["Börja med huvud, kropp och svansens riktning.","Forma spetsiga öron, lång nos, ben och pälsig bröstkorg.","Lägg till ögon, nos och mun.","Rita pälsens riktning och svansens yviga kontur."],
pafagel:["Markera hals, kropp och en stor solfjäderform bakom fågeln.","Forma hals, vingar, ben och de långa stjärtfjädrarna.","Lägg till näbb, öga och fjädrarnas ögonfläckar.","Rita fjäderlinjer och små detaljer i stjärten."],
delfin:["Rita en böjd kropp som en lång, avsmalnande oval.","Forma nos, ryggfena, sidofena och stjärtfenor.","Lägg till öga, mun och tydlig buklinje.","Avsluta fenornas konturer och några mjuka veck."],
pingvin:["Börja med en stor oval kropp och en mindre huvudform.","Forma vingar, näbb och två korta fötter.","Rita ögon och den ljusa magen.","Lägg till magens kontur och små fjäderlinjer."],
koala:["Markera huvud, kropp och två stora runda öron.","Forma armar och ben runt kroppen och lägg till en eukalyptuskvist.","Rita stora öron, ögon och den breda nosen.","Lägg till päls runt öronen och bladnerver på kvisten."],
orm:["Rita en mjuk S-form som visar hur kroppen slingrar sig.","Följ linjen med en jämn kropp och forma huvudet.","Lägg till ögon, mun och en kluven tunga.","Rita några jämna fjäll och förstärk kroppens kurvor."],
fenix:["Markera kropp, huvud och två stora vingriktningar.","Forma vingar, stjärtfjädrar, ben och huvudtofs.","Lägg till ögon, näbb och fjädergrupper.","Rita fjäderlinjer och avsluta med tydliga klor."],
blomma:["Börja med en liten cirkel för mitten och en linje för stjälken.","Rita fem eller sex stora kronblad runt mitten och två blad.","Lägg till mittprickar, bladnerver och en mjuk stjälk.","Gör kronbladens konturer tydliga och sudda hjälplinjerna."],
hus:["Rita en fyrkant och en triangel ovanpå som tak.","Lägg till dörr, fönster och skorsten.","Rita takpannor, fönsterkarmar och en liten gång.","Rätta till linjerna och lägg till några enkla detaljer."],
raket:["Börja med en lång oval kropp och en mittlinje.","Forma spetsig nos, två fenor och ett runt fönster.","Lägg till fönsterkant, motor och lågor.","Förstärk konturen och rita några små stjärnor runt raketen."],
bil:["Rita en lång kropp och en rundad båge för taket.","Forma hjul, fönster, stötfångare och lampor.","Lägg till hjulnav, dörrlinje och vindruta.","Färglägg bilen blå med svarta däck och gula lampor."],
paraply:["Rita ett handtag och en liten cirkel för paraplyets topp.","Forma paraplyets välvda tak och böjda handtag.","Dela taket i tygsektioner och lägg till en liten toppknopp.","Färglägg paraplyet rött, gult och blått med ett mörkt handtag."],
trad:["Rita en rak stam och markera var grenarna ska sitta.","Forma en bred krona med flera rundade bladklungor.","Lägg till grenar, blad och några små detaljer.","Färglägg stammen brun och kronan i olika gröna nyanser."],
bat:["Rita en lång vattenlinje och en enkel grundform för skrovet.","Forma en spetsig för, reling och en liten hytt.","Lägg till fönster, detaljer och mjuka vågor runt skrovet.","Färglägg båten röd och vit med blått vatten och fönster."],
pappersdrake:["Rita en romb och en lodrät och vågrät mittlinje.","Forma drakens fyra sidor, lång lina och svans.","Lägg till färgfält och små rosetter på svansen och linan.","Färglägg pappersdraken med tydliga röda, gula och blå fält."]
};
drawingAnimals.forEach(a=>{a.guide=drawingGuideAsset[a.id];a.steps=drawingDirections[a.id];a.subjectKind=a.subjectKind||"Djur";});
