function drawingGuideSprite(a){
 const file=drawingGuideAsset[a.id]||a.id+'.png';
 const image='assets/drawing-guides/'+file+'?v=20261018';
 return '<img class="draw-guide-sprite" src="'+image+'" alt="Fem ritsteg för '+a.name+', med färglagd bild i sista steget" loading="lazy">';
}
function drawingGallery(q){
 const levels=["Alla","Lätt","Medel","Svårt"];
 const visible=drawingAnimals.filter(a=>(drawingDifficulty==="Alla"||a.difficulty===drawingDifficulty)&&(drawingKind==="Alla"||a.subjectKind===drawingKind)&&(a.name+" "+a.id).toLocaleLowerCase("sv").includes(q));
 const kinds=["Alla","Djur","Saker"];
 let popup="";
 if(activeDrawing){
  const a=drawingAnimals.find(x=>x.id===activeDrawing);
  if(a){
   const picture='<div class="draw-modal-guides">'+drawingGuideSprite(a)+'</div>';
   const colorAdvice={katt:"grå, orange, svart eller vit päls",hund:"pälsfärg som passar hunden, till exempel brun eller svart",kanin:"vit, grå eller brun päls och rosa öron",fjaril:"starka, symmetriska färger på vingarna",panda:"svart och vit päls",lejon:"gyllengul päls och gyllenbrun man",rav:"orange päls, vit bringa och svanstipp samt svarta tassar",elefant:"grå hud och gärna rosa öron",uggla:"bruna fjädrar och ljus mage",skoldpadda:"gröna ben och ett grönt eller brunt skal",dinosaurie:"gröna eller jordnära färger",giraff:"gul päls med bruna fläckar",hast:"brun, svart eller fuxfärgad päls",tiger:"orange päls med svarta ränder och ljus mage",drake:"gröna fjäll och färgglada detaljer",varg:"grå eller brun päls",pafagel:"blå kropp och gröna, blå och gyllene stjärtfjädrar",delfin:"blågrå rygg och ljus mage",pingvin:"svart rygg, vit mage och orange näbb och fötter",koala:"grå päls, ljus mage och rosa öron",orm:"gröna eller bruna fjäll",fenix:"röda, orange och gyllene fjädrar",blomma:"färglägg kronblad, mitt och stjälk i olika färger",hus:"välj husfärger och en kontrasterande färg på taket",raket:"välj en tydlig färg på raketen och en annan på fönstret",bil:"välj en karossfärg och mörka däck"};const instructions=a.steps.concat("Färglägg bilden med "+(colorAdvice[a.id]||"färger som passar motivet")+".");popup='<div class="draw-modalback" data-close-draw><article class="draw-modal" role="dialog" aria-modal="true" aria-labelledby="drawModalTitle"><button class="draw-modal-close" data-close-draw aria-label="Stäng">×</button><div class="draw-modal-title"><span>'+a.emoji+'</span><div><h2 id="drawModalTitle">Så ritar du '+a.article+' '+a.name.toLocaleLowerCase("sv")+'</h2><p>'+a.difficulty+' · '+"5 sammanhängande bildsteg"+'</p></div></div>'+picture+'<ol class="draw-instructions">'+instructions.map(x=>"<li>"+x+"</li>").join("")+'</ol><p class="draw-tip-inline">Rita hjälplinjerna lätt med blyerts och sudda dem när teckningen är klar.</p></article></div>';
  }
 }
 return '<section class="draw-page"><div class="mandala-intro"><strong>Rita djur och andra motiv – ett tydligt bildsteg i taget</strong><p>Varje guide visar hur teckningen byggs upp och avslutas med ett färglagt exempel. Välj en svårighetsgrad och ett motiv.</p></div><div class="drawing-filters">'+kinds.map(v=>'<button class="mandala-type '+(drawingKind===v?"active":"")+'" data-draw-kind="'+v+'">'+v+'</button>').join("")+'</div><div class="drawing-filters">'+levels.map(v=>'<button class="mandala-type '+(drawingDifficulty===v?"active":"")+'" data-difficulty="'+v+'">'+v+'</button>').join("")+'</div><div class="mandala-grid draw-grid">'+visible.map(a=>'<button class="mandala-card draw-card" data-drawing="'+a.id+'">'+drawingGuideSprite(a)+'<span class="draw-card-title">'+a.emoji+' '+a.name+'<small>'+a.subjectKind+' · '+a.difficulty+' · 5 bildsteg · Visa guide →</small></span></button>').join("")+'</div>'+(visible.length?"":'<div class="empty">Inga motiv matchar valet.</div>')+popup+'</section>'
}
function pearlSvg(p){let w=Math.max(...p.rows.map(r=>r.length)),h=p.rows.length,step=22,pad=15,parts=['<svg class="pearl-svg" viewBox="0 0 '+(w*step+pad*2)+' '+(h*step+pad*2)+'" role="img" aria-label="Pärlplatta: '+p.name+'"><defs><filter id="pearlShadow" x="-30%" y="-30%" width="160%" height="170%"><feDropShadow dx="0" dy="2" stdDeviation="1.2" flood-color="#203a2d" flood-opacity=".2"/></filter></defs><rect x="2" y="2" width="'+(w*step+pad*2-4)+'" height="'+(h*step+pad*2-4)+'" rx="18" class="pearl-board"/>'];p.rows.forEach((row,y)=>{let offset=(w-row.length)/2;[...row].forEach((ch,x)=>{if(ch==="."||!pearlColors[ch])return;let cx=pad+(offset+x+.5)*step,cy=pad+(y+.5)*step;parts.push('<circle cx="'+cx+'" cy="'+cy+'" r="8.8" fill="'+pearlColors[ch]+'" class="pearl-bead" filter="url(#pearlShadow)"/><circle cx="'+(cx-2.2)+'" cy="'+(cy-2.6)+'" r="2" class="pearl-glint"/>')})});return parts.join("")+"</svg>"}
function pearlGallery(q){let visible=pearlPatterns.filter(p=>(pearlLevel==="Alla"||p.level===pearlLevel)&&(p.name+" "+p.palette).toLocaleLowerCase("sv").includes(q));if(selectedPearl){let p=pearlPatterns.find(x=>x.id===selectedPearl);if(!p){selectedPearl=null;return pearlGallery(q)}return '<div class="pearl-detail"><button class="secondary" data-pearl-back>← Alla mönster</button><div class="pearl-detail-grid">'+pearlSvg(p)+'<div><span class="pearl-level">'+p.level+'</span><h2>'+p.name+'</h2><p>Färger: '+p.palette+'</p><ol class="pearl-steps"><li>Placera pärlorna på en fyrkantig pärlplatta och följ bilden rad för rad.</li><li>Räkna från mitten så att mönstret hamnar rakt.</li><li>Be en vuxen stryka pärlorna enligt pärlornas instruktioner.</li><li>Låt mönstret svalna helt innan du lyfter det från plattan.</li></ol><button class="primary" data-pearl-print>Skriv ut mönstret</button></div></div></div>'}return '<div class="mandala-intro"><strong>Välj ett mönster och pärla bilden</strong><p>Varje bild visar exakt vilka färger du ska lägga på pärlplattan. Välj nivå för att hitta ett mönster som passar.</p></div><div class="drawing-filters">'+["Alla","Lätt","Medel","Svårt"].map(v=>'<button class="mandala-type '+(pearlLevel===v?'active':'')+'" data-pearl-level="'+v+'">'+v+'</button>').join("")+'</div><div class="mandala-grid pearl-grid">'+visible.map(p=>'<button class="mandala-card pearl-card" data-pearl="'+p.id+'">'+pearlSvg(p)+'<span class="pearl-card-title">'+p.name+'<small>'+p.level+' · '+p.palette+'</small></span></button>').join("")+'</div>'+(visible.length?'':'<div class="empty">Inga mönster hittades.</div>')}


function gymGallery(q){let games=gymGames.filter(g=>g.min<=gymStudents&&g.max>=gymStudents&&g.minutes<=gymMinutes&&(g.name+" "+g.description).toLocaleLowerCase("sv").includes(q));return '<div class="gym-intro"><strong>Fritidsgympa – lekar som passar er grupp</strong><p>Ange hur många elever ni är och hur lång tid ni har. Listan visar lekar som ryms inom tiden och fungerar för gruppstorleken. Tiderna inkluderar kort instruktion och flera rundor.</p></div><form class="gym-planner" id="gymPlanner"><label class="gym-field" for="gymStudents">Antal elever<input id="gymStudents" name="students" type="number" min="2" max="60" step="1" required value="'+gymStudents+'"></label><label class="gym-field" for="gymMinutes">Tid i minuter<input id="gymMinutes" name="minutes" type="number" min="5" max="120" step="5" required value="'+gymMinutes+'"></label><button class="primary" type="submit">Visa passande lekar</button></form><div class="gym-results">'+games.length+' lekar passar '+gymStudents+' elever på '+gymMinutes+' minuter</div><div class="grid gym-grid">'+games.map(g=>'<button type="button" class="card gym-card" data-gymgame="'+gymGames.indexOf(g)+'"><span class="gym-photo"><img loading="lazy" src="./assets/'+g.image+'" alt="Fotografi av '+g.name+'"></span><span class="ctext"><strong>'+g.name+'</strong><small>'+g.description+'</small><small>⏱ '+g.minutes+' min · '+g.min+'–'+g.max+' elever · '+g.materials+'</small></span><span class="arrow">›</span></button>').join("")+'</div>'+(games.length?'':'<div class="empty">Inga lekar passar just nu. Öka tiden eller ändra antalet elever.</div>')}


