$("#seasonPicker").addEventListener("click",()=>{updateSeasonMenu();const menu=$("#seasonMenu");menu.hidden=!menu.hidden;updateHalloweenControls()});
function closeThemeCodeGate(){const gate=$("#themeCodeGate");gate.hidden=true;$("#themeCodeInput").value="";$("#themeCodeError").textContent=""}
function requestThemeCode(theme){const gate=$("#themeCodeGate");gate.dataset.theme=theme;$("#themeCodeTitle").textContent=theme==="christmas"?"Lås upp jultemat":"Byt till Halloween";$("#themeCodeInput").value="";$("#themeCodeError").textContent="";gate.hidden=false;setTimeout(()=>$("#themeCodeInput").focus(),0)}
$("#themeCodeForm").addEventListener("submit",e=>{e.preventDefault();const gate=$("#themeCodeGate"),theme=gate.dataset.theme,code=$("#themeCodeInput").value.trim().toLocaleLowerCase("sv"),correct=theme==="christmas"?"julafton":"halloween";if(code!==correct){$("#themeCodeError").textContent="Koden stämmer inte. Försök igen.";$("#themeCodeInput").select();return}localStorage.fpThemeCodeUnlocked="1";closeThemeCodeGate();applySeasonTheme(theme)});
