$("#seasonMenu").addEventListener("click",e=>{const option=e.target.closest("[data-season-action]");if(!option||option.disabled)return;const action=option.dataset.seasonAction,christmasOn=document.body.classList.contains("christmas");$("#seasonMenu").hidden=true;if(action==="standard")applySeasonTheme("standard");else if(action==="christmas"&&autoChristmas)applySeasonTheme("christmas");else if(action==="christmas")requestThemeCode("christmas");else if(action==="halloween"&&autoHalloween)applySeasonTheme("halloween");else if(action==="halloween")requestThemeCode("halloween");updateHalloweenControls()});
