$("#theme").addEventListener("click",e=>{e.preventDefault();document.body.classList.toggle("dark");let dark=document.body.classList.contains("dark");localStorage.fpDark=dark?"1":"0";$("#theme").textContent=dark?"☀️":"🌙";$("#theme").setAttribute("aria-pressed",dark?"true":"false")});if(localStorage.fpDark==="1"&&!document.body.classList.contains("halloween")&&!document.body.classList.contains("christmas")){document.body.classList.add("dark");$("#theme").textContent="☀️";$("#theme").setAttribute("aria-pressed","true")}

